"""Arithmetic expression evaluator: tokenizer + recursive-descent parser.

Grammar (lowest to highest precedence):
    expression := term (('+' | '-') term)*
    term       := factor (('*' | '/' | '//' | '%') factor)*
    factor     := ('+' | '-') factor | power
    power      := atom ('**' factor)?
    atom       := NUMBER | '(' expression ')' | NAME '(' args ')'
"""


def _tokenize(text):
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c.isspace():
            i += 1
        elif c.isdigit() or c == '.':
            j = i
            seen_dot = False
            while j < n and (text[j].isdigit() or text[j] == '.'):
                if text[j] == '.':
                    if seen_dot:
                        break
                    seen_dot = True
                j += 1
            chunk = text[i:j]
            if chunk == '.':
                raise ValueError("malformed number literal")
            value = float(chunk) if seen_dot else int(chunk)
            tokens.append(('num', value))
            i = j
        elif c.isalpha() or c == '_':
            j = i
            while j < n and (text[j].isalpha() or text[j] == '_'):
                j += 1
            tokens.append(('name', text[i:j]))
            i = j
        elif text.startswith('**', i):
            tokens.append(('op', '**'))
            i += 2
        elif text.startswith('//', i):
            tokens.append(('op', '//'))
            i += 2
        elif c in '+-*/%(),':
            tokens.append(('op', c))
            i += 1
        else:
            raise ValueError("unexpected character %r" % c)
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return (None, None)

    def advance(self):
        token = self.peek()
        self.pos += 1
        return token

    def expect_op(self, op):
        kind, value = self.advance()
